o"}, {"label": "…navrhne konkrétny spoločný krok", "value": "konkretny_krok"}, {"label": "…mi dopraje priestor a ozve sa neskôr", "value": "priestor"}], "required": true}, {"key": "support_avoid", "type": "multi", "label": "Čo naopak pri podpore nechceš?", "options": [{"label": "Časté kontrolovanie", "value": "kontrola"}, {"label": "Nevyžiadané rady", "value": "rady"}, {"label": "Príliš priamu kritiku", "value": "kritika"}, {"label": "Tlak na výkon", "value": "tlak"}, {"label": "Príliš veľa správ", "value": "mnoho_sprav"}, {"label": "Riešenie veľmi osobných tém", "value": "osobne_temy"}, {"label": "Súťaženie a porovnávanie", "value": "sutazenie"}]}]}, {"id": "zaujmy", "title": "Záujmy a spoločný život", "questions": [{"key": "interests", "max": 5, "help": "Najviac päť možností.", "type": "multi", "label": "Čo ťa baví?", "options": [{"label": "Príroda a turistika", "value": "priroda"}, {"label": "Cestovanie a výlety", "value": "cestovanie"}, {"label": "Záhrada", "value": "zahrada"}, {"label": "Varenie alebo pečenie", "value": "varenie"}, {"label": "Knihy", "value": "knihy"}, {"label": "Divadlo, koncerty a kultúra", "value": "kultura"}, {"label": "Tanec", "value": "tanec"}, {"label": "Tvorenie a ručné práce", "value": "tvorenie"}, {"label": "Zvieratá", "value": "zvierata"}, {"label": "Osobný rozvoj", "value": "rozvoj"}, {"label": "Wellness", "value": "wellness"}, {"label": "Fitness a cvičenie", "value": "fitness"}, {"label": "Silový tréning", "value": "silovy_trening"}, {"label": "Joga a strečing", "value": "joga"}, {"label": "Beh a behanie", "value": "beh"}, {"label": "Bicykel", "value": "bicykel"}, {"label": "Plávanie", "value": "plavanie"}, {"label": "Fotografia", "value": "fotografia"}, {"label": "Dobrovoľníctvo", "value": "dobrovolnictvo"}, {"label": "Káva a pokojné rozhovory", "value": "kava"}], "required": true}, {"key": "club_activities", "type": "multi", "label": "Na aké klubové aktivity by si reálne prišla?", "options": [{"label": "Regionálna prechádzka", "v